/* eslint-env mocha */
import { FunctionTree } from './'
import assert from 'assert'

describe('FunctionTreeExecution', () => {
  it('should pass error with payload property', (done) => {
    const ft = new FunctionTree()

    ft.run(
      [
        ({ _execution }) => {
          return Promise.reject(new Error('wuuut'))
        },
      ],
      { prop1: 'value', prop2: 'value' }
    ).catch((error) => {
      assert.strictEqual(error.message, 'wuuut')
      assert.strictEqual(error.payload.error.name, 'Error')
      assert.strictEqual(error.payload.error.message, 'wuuut')
      done()
    })
  })
  it('should stop if throw from async action', (done) => {
    const ft = new FunctionTree()

    ft.run([
      ({ _execution }) => {
        return Promise.reject(new Error())
      },
      ({ _execution }) => {
        done(new Error('Should not continue execution.'))
      },
    ]).catch(() => {
      done()
    })
  })
  it('should pass error with payload property', (done) => {
    const ft = new FunctionTree()

    ft.run(
      [
        ({ _execution }) => {
          return Promise.reject(new Error('wuuut'))
        },
      ],
      { prop1: 'value', prop2: 'value' }
    ).catch((error) => {
      assert.strictEqual(error.message, 'wuuut')
      assert.strictEqual(error.payload.error.name, 'Error')
      assert.strictEqual(error.payload.error.message, 'wuuut')
      done()
    })
  })
  it('should throw to console if not catch handler', (done) => {
    const ft = new FunctionTree()

    process.once('unhandledRejection', () => {
      done()
    })

    ft.run([
      ({ _execution }) => {
        throw new Error()
      },
      ({ _execution }) => {
        done(new Error('Should not continue execution.'))
      },
    ])
  })
  it('should pass final payload in event', (done) => {
    const ft = new FunctionTree()
    ft.once('error', (_, execution, funcDetails, payload) => {
      setTimeout(() => {
        assert.deepStrictEqual(payload, { prop1: 'value', prop2: 'updated' })
        done()
      })
    })

    ft.run(
      {
        prop1: 'value',
        prop2: 'updated',
      },
      [
        ({ _execution }) => {
          throw new Error()
        },
        ({ _execution }) => {
          done(new Error('Should not continue execution.'))
        },
      ]
    ).catch(() => {})
  })
  it('should use error toJSON, if available, to serialize error', (done) => {
    const ft = new FunctionTree()

    class CustomError {
      constructor(message) {
        this.name = 'CustomError'
        this.message = message
      }

      toJSON() {
        return this.message
      }
    }
    ft.run(
      [
        () => {
          throw new CustomError('foo')
        },
      ],
      {}
    ).catch((error) => {
      assert.ok(error instanceof CustomError)
      assert.strictEqual(error.payload.error, 'foo')
      done()
    })
  })
})
